local src
for _, r in ipairs(ns.ROUTES) do if r.id == "forsaken" then src = r end end
if not src then return end
local brackets = {}
for _, b in ipairs(OPT) do table.insert(brackets, b) end
for i = 4, #src.brackets do table.insert(brackets, src.brackets[i]) end
table.insert(ns.ROUTES, {
  id = "forsaken-opt", name = src.name .. " (optimized)", faction = src.faction,
  races = src.races, raceOnly = src.raceOnly, optimized = true,
  brackets = brackets,
})
